'use strict';
const icons={chat:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z',search:'m21 21-4.5-4.5 M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',trash:'M3 6h18M9 6V4h6v2M5 6l1 15h12l1-15M10 10v7M14 10v7',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',thought:'M8 10h8M8 14h5M20 11a8 8 0 1 0-8 8h3l4 2-1-5a8 8 0 0 0 2-5',arrow:'m5 12 14 0m-6-6 6 6-6 6',back:'m15 5-7 7 7 7',download:'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5',edit:'m16 3 5 5-12 12-6 1 1-6L16 3ZM13 6l5 5',close:'m6 6 12 12M6 18 18 6',restore:'M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v6l4 2',check:'m5 12 4 4L19 6'};
const svg=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="${icons[n]||icons.chat}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();const now=()=>new Date().toISOString();const ym=d=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',timeZone:'Asia/Taipei'}).format(new Date(d)).replace('/','-');
const month=d=>ym(d).replace('-','.');
let KEY='minerva-room-v1';
const categoryPalette=['#c2ab74','#83a999','#bc9192','#a194b3','#8b9c73','#91a2b2'];
const validColor=color=>typeof color==='string'&&/^#[0-9a-f]{6}$/i.test(color);
const categoryColor=id=>{const c=db.categories.find(c=>c.id===id);return validColor(c?.color)?c.color:'#8b9c73'};
const avatarStyle=id=>`background:${categoryColor(id)}22;color:${categoryColor(id)}`;
function seed(){const at=now();return{version:1,categories:['興趣','健康','愛人','朋友','公事','社會'].map(name=>({id:uid(),name})),chats:[],trash:[],seededAt:at}}
function validateDatabase(data){
 const fail=()=>{throw Error('儲存資料格式不符，已停止寫入以保留原始內容。')};
 const obj=v=>{if(!v||typeof v!=='object'||Array.isArray(v))fail()};
 const text=(v,n=20000)=>{if(typeof v!=='string'||v.length>n)fail()};
 const id=v=>{if(typeof v!=='string'||!/^[a-zA-Z0-9_-]{1,128}$/.test(v))fail()};
 const date=(v,optional=false)=>{if(optional&&v==='')return;if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}(?:T[0-9:.]+Z)?$/.test(v)||Number.isNaN(Date.parse(v)))fail()};
 const list=(v,check)=>{if(!Array.isArray(v)||v.length>100000)fail();const ids=new Set();for(const x of v){obj(x);id(x.id);if(ids.has(x.id))fail();ids.add(x.id);check(x)}};
 const hypothesis=h=>text(h.text);
 const thought=t=>{text(t.text);list(t.hypotheses,hypothesis)};
 const message=m=>{if(!['me','other'].includes(m.role))fail();text(m.text);date(m.createdAt);date(m.eventDate,true);list(m.thoughts,thought)};
 const chat=c=>{id(c.categoryId);text(c.name,100);date(c.createdAt);list(c.messages,message)};
 obj(data);if(data.version!==1)fail();list(data.categories,c=>{text(c.name,30);if(c.color!==undefined&&!validColor(c.color))fail()});if(!data.categories.length)fail();list(data.chats,chat);
 list(data.trash,x=>{date(x.deletedAt);text(x.label,500);text(x.summary,2000);obj(x.payload);const p=x.payload;if(x.type==='chats'){list(p.chats,chat)}else{if(!['messages','thought','hypothesis'].includes(x.type))fail();id(p.chatId);if(x.type==='messages'){if(!Array.isArray(p.messages))fail();p.messages.forEach(v=>{obj(v);if(!Number.isInteger(v.index)||v.index<0)fail();obj(v.data);id(v.data.id);message(v.data)})}else{id(p.messageId);if(!Number.isInteger(p.index)||p.index<0)fail();obj(p.data);id(p.data.id);if(x.type==='thought')thought(p.data);else{id(p.thoughtId);hypothesis(p.data)}}}});return data;
}
let db,rawStored=null,loadError=false,storageIssue='';
try{rawStored=localStorage.getItem(KEY);if(rawStored!==null&&rawStored.length>20000000)throw Error('資料過大');db=rawStored===null?seed():validateDatabase(JSON.parse(rawStored))}catch{db=seed();loadError=true;storageIssue='無法讀取原有紀錄。已停止寫入，請先下載原始資料備份。'}
let lastSaved=structuredClone(db),lastRaw=rawStored,externalChange=false;
if(rawStored===null&&!loadError){const t=now(),cats=db.categories;db.chats=[{id:uid(),categoryId:cats[3].id,name:'金多美',isDemo:true,createdAt:t,messages:[{id:uid(),role:'other',text:'最近過得怎麼樣？週末要不要一起喝杯咖啡？',createdAt:t,eventDate:'',thoughts:[{id:uid(),text:'看到邀約覺得很開心，也想到自己最近好像一直忙著工作。想留一點時間，和朋友聊聊近況。',hypotheses:[{id:uid(),text:'她可能也想找個人聊聊最近的生活。'}]}]},{id:uid(),role:'me',text:'好呀，週六下午我有空。我們去上次那間店？',createdAt:t,eventDate:'',thoughts:[]},{id:uid(),role:'other',text:'好！那就下午三點見 ☕',createdAt:t,eventDate:'',thoughts:[]}]},...cats.filter((_,i)=>i!==3).map(c=>({id:uid(),categoryId:c.id,name:'',createdAt:t,messages:[]}))];}
db.categories.forEach((c,i)=>{if(!validColor(c.color))c.color=categoryPalette[i%categoryPalette.length]});
db.trash=db.trash.filter(x=>Date.now()-new Date(x.deletedAt).getTime()<30*86400000);lastSaved=structuredClone(db);
let state={active:db.chats[0]?.id,category:'',date:'',query:'',inQuery:'',showSearch:false,page:'chats',mobileChat:false,chatBatch:false,msgBatch:false,selectedChats:new Set(),selectedMessages:new Set(),edit:null,role:'other',thoughtFor:null,insertAfter:null,inlineCreate:null};
const agentAccess={enabled:false,write:false,chatIds:new Set()};let agentLifecycle=null;
function requireAgentAccess(chatId,write=false){if(cloudGate&&!cloudState.ready)throw Error('Please sign in first.');if(!agentAccess.enabled||chatId&&!agentAccess.chatIds.has(chatId)||write&&!agentAccess.write)throw Error('This chat or operation has not been shared with AI in this session.');}
function setAgentAccess(ids,write=false){agentLifecycle?.abort();agentLifecycle=null;agentAccess.chatIds=new Set(ids.filter(id=>db.chats.some(c=>c.id===id)));agentAccess.enabled=agentAccess.chatIds.size>0;agentAccess.write=agentAccess.enabled&&write;renderKeepDraft();return registerAgentTools()}
function aiSettings(){openModal('AI 存取設定',`<p>預設關閉。選取的聊天包含現實行動、思緒與假設。此設定只在這次開啟頁面期間有效。</p><div class="ai-chat-options">${db.chats.map(c=>`<label class="check-row"><input type="checkbox" name="sharedChat" value="${e(c.id)}" ${agentAccess.chatIds.has(c.id)?'checked':''}>${e(chatTitle(c))}</label>`).join('')}</div><label class="check-row"><input type="checkbox" name="allowWrite" ${agentAccess.write?'checked':''}>允許 AI 新增現實行動與思緒</label><p>取消勾選所有聊天並儲存，即關閉 AI 工具。一般頁面內容仍可能被你使用的瀏覽器助理讀取。</p>`,fd=>{void setAgentAccess(fd.getAll('sharedChat'),fd.get('allowWrite')==='on');notify('AI 存取設定已更新')})}
window.addEventListener('pagehide',()=>{agentAccess.enabled=false;agentLifecycle?.abort()});
let toastTimer;const app=document.getElementById('app'),modal=document.getElementById('modal');
function notify(text,undo){const box=document.getElementById('status');box.textContent=text;if(undo){const b=document.createElement('button');b.textContent='復原';b.onclick=undo;box.append(b)}box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),7000)}
class StorageFailure extends Error{}
function persist(){try{if(cloudGate&&!cloudState.ready)throw new StorageFailure('請先登入並載入雲端紀錄');if(cloudState.ready)db._cloud={revision:cloudState.base.revision,dirty:true};if(loadError)throw new StorageFailure('原始資料讀取異常，已阻止覆寫。請下載原始資料備份。');if(externalChange||localStorage.getItem(KEY)!==lastRaw)throw new StorageFailure('其他分頁已更新資料。請先備份未儲存內容，再重新整理。');validateDatabase(db);const serialized=JSON.stringify(db);localStorage.setItem(KEY,serialized);lastRaw=serialized;lastSaved=structuredClone(db);storageIssue='';if(cloudState.ready)queueCloudSave(db);return true}catch(error){db=structuredClone(lastSaved);storageIssue=error instanceof StorageFailure?error.message:'儲存失敗，這次變更尚未保存。請保留輸入內容並確認瀏覽器儲存空間。';throw new StorageFailure(storageIssue)}}
function guarded(handler){return function(...args){try{return handler.apply(this,args)}catch(error){if(error instanceof StorageFailure){renderKeepDraft();notify(error.message)}else{console.error(error);notify('操作未完成，請保留內容後重試。')}}}}
function downloadJson(content,name){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

const categoryName=id=>db.categories.find(c=>c.id===id)?.name||'未分類';const chatTitle=c=>c.name||categoryName(c.categoryId);const current=()=>db.chats.find(c=>c.id===state.active);const findMessage=id=>current()?.messages.find(m=>m.id===id);
const findThought=(mid,tid)=>findMessage(mid)?.thoughts.find(t=>t.id===tid);
function allText(c){return[chatTitle(c),categoryName(c.categoryId),...c.messages.flatMap(m=>[m.text,...m.thoughts.flatMap(t=>[t.text,...t.hypotheses.map(h=>h.text)])])].join(' ').toLocaleLowerCase()}
function filteredChats(){return db.chats.filter(c=>(!state.category||c.categoryId===state.category)&&(!state.date||ym(c.createdAt)===state.date)&&(!state.query||allText(c).includes(state.query.toLocaleLowerCase())))}
const btn=(action,text,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const ib=(action,icon,label,extra='')=>btn(action,svg(icon),'icon',`aria-label="${e(label)}" title="${e(label)}" ${extra}`);
function render(){if(cloudGate&&!cloudState.ready){app.className='cloud-locked';app.innerHTML=renderCloudGate();return}const scroll=document.getElementById('timeline')?.scrollTop||0;const c=current();app.className=state.mobileChat?'chat-active':'';
app.innerHTML=`<aside class="rail" aria-label="主要導覽"><nav>${btn('page-chats',svg('chat')+'聊天紀錄 <span class="count">'+db.chats.length+'</span>','nav-btn '+(state.page==='chats'?'active':''))}${btn('page-trash',svg('trash')+'回收桶 <span class="count">'+db.trash.length+'</span>','nav-btn '+(state.page==='trash'?'active':''))}</nav><div class="cat-heading"><span class="eyebrow">我的分類</span>${ib('categories','settings','管理分類')}</div><nav aria-label="聊天分類">${btn('filter-category','<span class="dot" style="background:#a2a68f"></span>全部紀錄','category '+(!state.category?'active':''),'data-id=""')}${db.categories.map((x,i)=>btn('filter-category',`<span class="dot" style="background:${categoryColor(x.id)}"></span>${e(x.name)}`,'category '+(state.category===x.id?'active':''),`data-id="${e(x.id)}"`)).join('')}</nav><div class="rail-foot">${btn('cloud-settings',e(cloudLabel()),'text-btn')}${btn('ai-settings',agentAccess.enabled?'AI 存取：已啟用':'AI 存取：關閉','text-btn')}<p>${cloudState.ready?e(cloudState.status):'僅儲存在此瀏覽器'}</p>${btn('export','匯出紀錄 JSON','text-btn')}</div></aside>
<section class="chat-panel" aria-label="聊天列表"><header class="list-head"><div class="title-row"><h2>聊天</h2>${ib('new-chat','plus','新增聊天')}</div><div class="search">${svg('search')}<label for="global-search" hidden>搜尋分類、人物或紀錄</label><input id="global-search" type="search" placeholder="搜尋分類、人物或紀錄…" value="${e(state.query)}"></div><div class="filter-row"><label for="category-filter" hidden>依分類篩選聊天</label><select id="category-filter"><option value="">全部分類</option>${db.categories.map(x=>`<option value="${e(x.id)}" ${state.category===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select><label for="date-filter" hidden>依聊天建立年月篩選</label><input id="date-filter" type="month" aria-label="依聊天建立年月篩選" value="${e(state.date)}" title="依聊天建立年月篩選"></div></header><div class="list-meta"><span>${filteredChats().length} 個聊天${state.date?' · 建立年月':''}</span><div>${state.category||state.date||state.query?btn('clear-filters','清除篩選','text-btn'):''}${btn('chat-batch',state.chatBatch?'完成':'批次管理','text-btn')}</div></div>${state.chatBatch?`<div class="batchbar"><span>已選 ${state.selectedChats.size} 個</span>${btn('select-chats','全選','text-btn')}${btn('batch-chat-edit','更改分類','btn',state.selectedChats.size?'':'disabled')}${btn('batch-chat-delete','刪除','btn danger',state.selectedChats.size?'':'disabled')}</div>`:''}<div class="mobile-bar">${btn('page-chats','聊天','text-btn')}${btn('page-trash','回收桶','text-btn')}${btn('categories','管理分類','text-btn')}${btn('ai-settings','AI 存取','text-btn')}${btn('cloud-settings',e(cloudLabel()),'text-btn')}</div><div class="chat-list">${filteredChats().map(x=>{const preview=x.messages.at(-1)?.text||'留一個空間，開始記錄';return`<article class="chat-item ${x.id===state.active?'active':''}" data-chat-id="${e(x.id)}">${state.chatBatch?`<input type="checkbox" data-select-chat="${e(x.id)}" aria-label="選取聊天 ${e(chatTitle(x))}" ${state.selectedChats.has(x.id)?'checked':''}>`:''}<button class="chat-open" data-action="open-chat" data-id="${e(x.id)}" aria-label="開啟聊天 ${e(chatTitle(x))}" ${x.id===state.active?'aria-current="true"':''}><span class="avatar" data-cat="${e(categoryName(x.categoryId))}" style="${avatarStyle(x.categoryId)}">${e(chatTitle(x).slice(0,1))}</span><div class="chat-copy"><div class="chat-top"><strong>${e(chatTitle(x))}</strong><time datetime="${e(x.createdAt)}">${month(x.createdAt)}</time></div><p class="preview">${e(preview)}</p><p class="chat-category">${e(categoryName(x.categoryId))}</p></div></button></article>`}).join('')||'<div class="empty">沒有符合的聊天紀錄</div>'}</div><footer class="list-bottom"><span class="mobile-only">${btn('export','匯出','text-btn')}</span></footer></section>
${state.page==='trash'?renderTrash():c?renderChat(c):`<main class="conversation"><div class="empty">${storageIssue?`<p role="alert">${e(storageIssue)}</p>${btn('export-original','下載原始儲存資料','btn')}`:''}<h3>為一段互動留個位置</h3><p>建立聊天，記下現實中的互動與思緒。</p>${btn('new-chat','新增聊天','btn primary')}</div></main>`}`;
const tl=document.getElementById('timeline');if(tl)tl.scrollTop=scroll;
}
function renderChat(c){const matches=c.messages.filter(m=>!state.inQuery||[m.text,...m.thoughts.flatMap(t=>[t.text,...t.hypotheses.map(h=>h.text)])].join(' ').toLocaleLowerCase().includes(state.inQuery.toLocaleLowerCase()));return`<main class="conversation" aria-label="${e(chatTitle(c))}的私人紀錄"><header class="conversation-head"><div class="person">${btn('back',svg('back'),'icon mobile-back','aria-label="返回聊天列表"')}<span class="avatar" data-cat="${e(categoryName(c.categoryId))}" style="${avatarStyle(c.categoryId)}">${e(chatTitle(c).slice(0,1))}</span><div><h2>${e(chatTitle(c))}</h2><p>${e(categoryName(c.categoryId))} <span aria-hidden="true">／</span> 私人互動紀錄</p></div></div><div class="head-actions">${ib('in-search','search','搜尋此聊天')}${ib('msg-batch','check',state.msgBatch?'結束多選':'批次編輯紀錄')}${ib('chat-settings','settings','聊天設定')}</div></header>${state.showSearch?`<div class="conversation-search"><label for="in-search" hidden>搜尋此聊天的紀錄</label><input id="in-search" type="search" placeholder="搜尋此聊天的紀錄…" value="${e(state.inQuery)}"><span>${matches.length} 則現實行動</span>${ib('close-search','close','關閉聊天搜尋')}</div>`:''}${state.msgBatch?`<div class="batchbar"><span>已選 ${state.selectedMessages.size} 則現實行動</span>${btn('select-messages','全選','text-btn')}${btn('batch-role-me','改為「我」','btn',state.selectedMessages.size?'':'disabled')}${btn('batch-role-other','改為「對方」','btn',state.selectedMessages.size?'':'disabled')}${btn('batch-message-delete','刪除','btn danger',state.selectedMessages.size?'':'disabled')}${btn('msg-batch','完成','text-btn')}</div>`:''}<section id="timeline" class="timeline" aria-label="現實互動時間軸" tabindex="-1">${storageIssue?`<div class="storage-alert" role="alert"><p>${e(storageIssue)}</p>${btn('export-original','下載原始儲存資料','text-btn')}</div>`:''}<div class="month"><time datetime="${ym(c.createdAt)}">${month(c.createdAt)}</time></div><p class="intro">${c.isDemo?'這是一段示範紀錄，可自由編輯或刪除。':'這裡的對話與思緒，都由你自由記錄。'}<br>每個想法，都可以先留在這裡。</p>${matches.map(renderMessage).join('')||`<div class="empty">${state.inQuery?'沒有符合的紀錄':'從一則現實互動開始。'}</div>`}</section>${renderComposer(c)}</main>`}
function editForm(type,id,text,mid='',tid=''){return`<form class="inline-form" data-edit-type="${type}" data-id="${e(id)}" data-mid="${e(mid)}" data-tid="${e(tid)}"><label class="small" for="inline-${e(id)}">編輯${{message:'現實行動',thought:'思緒',hypothesis:'待驗證假設'}[type]}</label><textarea id="inline-${e(id)}" name="text" required rows="3" maxlength="20000">${e(text)}</textarea>${type==='message'?`<label class="small" for="edit-role">記錄對象</label><select id="edit-role" name="role"><option value="other" ${findMessage(id).role==='other'?'selected':''}>對方</option><option value="me" ${findMessage(id).role==='me'?'selected':''}>我</option></select><label class="small" for="edit-date">事件日期（選填）</label><input id="edit-date" name="eventDate" type="date" value="${e(findMessage(id).eventDate)}">`:''}<div class="edit-actions">${btn('cancel-edit','取消','btn')}<button class="btn primary" type="submit">儲存</button></div></form>`}
function renderMessage(m){const locked=state.msgBatch;return`<article class="message ${m.role==='me'?'mine':''}" data-message-id="${e(m.id)}" aria-label="${m.role==='me'?'我':'對方'}的現實行動"><div class="message-heading">${locked?`<input type="checkbox" data-select-message="${e(m.id)}" aria-label="選取現實行動 ${e(m.text.slice(0,30))}" ${state.selectedMessages.has(m.id)?'checked':''}>`:''}<span>${m.role==='me'?'我':'對方'} · 現實行動</span>${m.eventDate?`<time datetime="${e(m.eventDate)}">${e(m.eventDate)}</time>`:''}</div>${state.edit?.id===m.id?`<div class="inline-edit">${editForm('message',m.id,m.text)}</div>`:locked?`<div class="bubble">${e(m.text)}</div>`:btn('edit-message',e(m.text),'bubble',`data-id="${e(m.id)}" aria-label="編輯現實行動：${e(m.text.slice(0,40))}"`)}${!locked?`<div class="message-actions">${btn('add-thought',svg('plus')+'新增思緒','mini-btn',`data-id="${e(m.id)}"`)}${ib('delete-message','trash','刪除此現實行動及附著思緒',`data-id="${e(m.id)}"`)}</div>`:''}${m.thoughts.map(t=>renderThought(m,t,locked)).join('')}${!locked&&state.inlineCreate?.messageId===m.id&&state.inlineCreate.kind==='thought'?renderInlineCreate(m,'thought'):''}${!locked?`<div class="insertion-row">${btn('insert',svg('plus')+'在此插入現實行動','mini-btn',`data-id="${e(m.id)}"`)}</div>`:''}${!locked&&state.inlineCreate?.messageId===m.id&&state.inlineCreate.kind==='message'?renderInlineCreate(m,'message'):''}</article>`}
function renderInlineCreate(m,kind){const d=state.inlineCreate;const thought=kind==='thought';return`<section class="${thought?'thought thought-draft':'inline-reality '+(d.role==='me'?'mine':'')}" data-parent-message-id="${e(m.id)}" aria-label="${thought?'新增附著思緒':'在此插入現實行動'}"><form data-create-kind="${kind}" data-mid="${e(m.id)}"><div class="${thought?'thought-head':'inline-create-title'}">${thought?'新增思緒':'插入現實行動'}</div>${!thought?`<div class="composer-tabs" role="group" aria-label="插入行動的記錄對象">${['other','me'].map(r=>btn('inline-role',r==='me'?'我':'對方','chip '+(d.role===r?'active':''),`data-role="${r}" aria-pressed="${d.role===r}"`)).join('')}</div>`:''}<label for="create-${e(m.id)}" hidden>${thought?'思緒內容':'現實行動內容'}</label><textarea id="create-${e(m.id)}" name="text" required maxlength="20000" rows="3" placeholder="${thought?'此刻，你想到了什麼？':'記下對方或自己的實際言語、行動…'}">${e(d.text)}</textarea><div class="edit-actions">${btn('cancel-create','取消','btn')}<button type="submit" class="btn primary">${thought?'新增思緒':'插入紀錄'}</button></div></form></section>`}
function renderThought(m,t,locked){return`<section class="thought" data-thought-id="${e(t.id)}" data-parent-message-id="${e(m.id)}" aria-label="我的思緒，附著於${m.role==='me'?'我':'對方'}的現實行動"><div class="thought-head"><span>${svg('thought')} 當時的思緒</span>${!locked?ib('delete-thought','trash','刪除此思緒及待驗證假設',`data-mid="${e(m.id)}" data-id="${e(t.id)}"`):''}</div>${state.edit?.id===t.id?editForm('thought',t.id,t.text,m.id):locked?`<p class="thought-text">${e(t.text)}</p>`:btn('edit-thought',e(t.text),'thought-text',`data-mid="${e(m.id)}" data-id="${e(t.id)}" aria-label="編輯思緒：${e(t.text.slice(0,40))}"`)}<p class="anchor">↳ 回應${m.role==='me'?'我的':'對方的'}現實行動</p>${t.hypotheses.length?`<div class="hypotheses"><div class="hyp-title">待驗證假設</div>${t.hypotheses.map(h=>`<div class="hyp" data-hypothesis-id="${e(h.id)}">${state.edit?.id===h.id?editForm('hypothesis',h.id,h.text,m.id,t.id):locked?`<p class="hyp-text">${e(h.text)}</p>`:btn('edit-hypothesis',e(h.text),'hyp-text',`data-mid="${e(m.id)}" data-tid="${e(t.id)}" data-id="${e(h.id)}" aria-label="編輯待驗證假設：${e(h.text.slice(0,40))}"`)}${!locked?ib('delete-hypothesis','trash','刪除此待驗證假設',`data-mid="${e(m.id)}" data-tid="${e(t.id)}" data-id="${e(h.id)}"`):''}</div>`).join('')}</div>`:''}${!locked?btn('add-hypothesis',svg('plus')+'待驗證假設','mini-btn',`data-mid="${e(m.id)}" data-id="${e(t.id)}"`):''}</section>`}
function renderComposer(c){return`<form id="composer" class="composer"><div class="composer-tabs" role="group" aria-label="新增現實行動的記錄對象">${['other','me'].map(r=>btn('compose-role',r==='other'?'對方':'我','chip '+(state.role===r?'active':''),`data-role="${r}" aria-pressed="${state.role===r}" ${state.msgBatch?'disabled':''}`)).join('')}</div><label for="draft" hidden>記錄現實中發生的互動</label><textarea id="draft" name="text" placeholder="${state.msgBatch?'批次選取中，完成後可繼續記錄':'記下對方或自己的實際言語、行動…'}" rows="2" maxlength="20000" required ${state.msgBatch?'disabled':''}></textarea><div class="composer-foot"><span class="composer-label">Enter 換行 · Ctrl / ⌘ + Enter 加入紀錄</span><button type="submit" class="btn primary" ${state.msgBatch?'disabled':''}>加入紀錄 ${svg('arrow')}</button></div></form>`}
function renderTrash(){return`<main class="conversation"><header class="conversation-head"><div class="person">${btn('back',svg('back'),'icon mobile-back','aria-label="返回聊天列表"')}<div><h2>回收桶</h2><p>刪除後保留 30 天，可在這裡復原。</p></div></div></header><section id="timeline" class="timeline" aria-label="可復原的已刪除紀錄">${db.trash.map(x=>`<article class="trash-card"><div><h3>${e(x.label)}</h3><p>${e(x.summary)} · ${month(x.deletedAt)}</p></div>${btn('restore',svg('restore')+'復原','btn',`data-id="${e(x.id)}"`)}</article>`).join('')||'<div class="empty">回收桶目前是空的。</div>'}</section></main>`}
function openModal(title,body,onSubmit,destructive=false){document.getElementById('modal-body').innerHTML=`<form id="modal-form"><h2 id="modal-title">${e(title)}</h2>${body}<div class="modal-actions">${btn('modal-cancel','取消','btn')}<button type="submit" class="btn primary ${destructive?'danger':''}">${destructive?'確認刪除':'儲存'}</button></div></form>`;if(!modal.open)modal.showModal();document.getElementById('modal-form').onsubmit=ev=>{ev.preventDefault();try{if(onSubmit(new FormData(ev.currentTarget))!==false)modal.close()}catch(error){notify(error.message);renderKeepDraft()}};if(destructive)modal.querySelector('[data-action="modal-cancel"]').focus()}
function pushTrash(type,payload,label,summary){const item={id:uid(),type,payload:structuredClone(payload),label,summary,deletedAt:now()};db.trash.unshift(item);return item.id}
function restore(id){const x=db.trash.find(x=>x.id===id);if(!x)return;const p=x.payload;if(x.type==='chats'){for(const c of p.chats)if(!db.chats.some(v=>v.id===c.id))db.chats.push(c)}else{const c=db.chats.find(c=>c.id===p.chatId);if(!c){notify('請先復原所屬聊天，再復原此紀錄。');return}if(x.type==='messages'){p.messages.sort((a,b)=>a.index-b.index).forEach(v=>{if(!c.messages.some(m=>m.id===v.data.id))c.messages.splice(Math.min(v.index,c.messages.length),0,v.data)})}else{const m=c.messages.find(m=>m.id===p.messageId);if(!m){notify('請先復原所屬現實行動。');return}if(x.type==='thought'){m.thoughts.splice(Math.min(p.index,m.thoughts.length),0,p.data)}else{const t=m.thoughts.find(t=>t.id===p.thoughtId);if(!t){notify('請先復原所屬思緒。');return}t.hypotheses.splice(Math.min(p.index,t.hypotheses.length),0,p.data)}}}db.trash=db.trash.filter(v=>v.id!==id);if(!state.active)state.active=db.chats[0]?.id;persist();render();notify('已復原紀錄')}
function confirmDelete(kind,ids,{mid,tid}={}){const c=current();let label,summary,quote='',run;const chatId=c?.id;
if(kind==='chats'){const targets=db.chats.filter(v=>ids.includes(v.id));if(!targets.length)return;label=`${targets.length} 個聊天`;const ms=targets.flatMap(c=>c.messages);summary=impact(ms);quote=targets.map(chatTitle).join('、');run=()=>{const trashId=pushTrash('chats',{chats:targets},label,summary);db.chats=db.chats.filter(v=>!ids.includes(v.id));if(ids.includes(state.active))state.active=db.chats[0]?.id;state.selectedChats.clear();return trashId}}
if(kind==='messages'){const targets=c.messages.filter(v=>ids.includes(v.id));if(!targets.length)return;label=`${targets.length} 則現實行動`;summary=impact(targets);quote=targets.map(v=>v.text).join('\n');run=()=>{const trashId=pushTrash('messages',{chatId,messages:targets.map(data=>({index:c.messages.indexOf(data),data}))},label,summary);c.messages=c.messages.filter(v=>!ids.includes(v.id));state.selectedMessages.clear();if(ids.includes(state.thoughtFor))state.thoughtFor=null;if(ids.includes(state.insertAfter))state.insertAfter=null;return trashId}}
if(kind==='thought'){const m=findMessage(mid),t=m?.thoughts.find(v=>v.id===ids[0]);if(!t)return;label='這張思緒卡';summary=`包含 ${t.hypotheses.length} 筆待驗證假設；保留所屬現實行動。`;quote=t.text;run=()=>{const id=pushTrash('thought',{chatId,messageId:mid,index:m.thoughts.indexOf(t),data:t},'思緒',summary);m.thoughts=m.thoughts.filter(v=>v.id!==t.id);return id}}
if(kind==='hypothesis'){const t=findThought(mid,tid),h=t?.hypotheses.find(v=>v.id===ids[0]);if(!h)return;label='這筆待驗證假設';summary='只刪除此假設，保留所屬思緒與現實行動。';quote=h.text;run=()=>{const id=pushTrash('hypothesis',{chatId,messageId:mid,thoughtId:tid,index:t.hypotheses.indexOf(h),data:h},'待驗證假設',summary);t.hypotheses=t.hypotheses.filter(v=>v.id!==h.id);return id}}
if(!run)throw Error('找不到刪除對象');openModal(`刪除${label}？`,`<p>${e(summary)}</p><blockquote>${e(quote)}</blockquote><p>確認後移至回收桶，保留 30 天。期間可以復原。</p>`,()=>{const id=run();persist();render();notify('已移至回收桶',()=>restore(id))},true)}
function impact(messages){return`包含 ${messages.length} 則現實行動、${messages.reduce((a,m)=>a+m.thoughts.length,0)} 張思緒卡及 ${messages.reduce((a,m)=>a+m.thoughts.reduce((b,t)=>b+t.hypotheses.length,0),0)} 筆待驗證假設。`}
function chatForm(c){openModal(c?'聊天設定':'新增聊天',`<label for="chat-category">分類</label><select id="chat-category" name="categoryId" required>${db.categories.map(x=>`<option value="${e(x.id)}" ${c?.categoryId===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select><label for="chat-name">人物名稱（選填）</label><input id="chat-name" name="name" maxlength="100" value="${e(c?.name||'')}" placeholder="留空時，顯示分類名稱">${c?`<p>建立於 ${month(c.createdAt)}</p>${btn('delete-chat',svg('trash')+'刪除這個聊天','btn danger')}`:'<p>所有內容均由你記錄，其他人物不會收到訊息。</p>'}`,fd=>{if(!db.categories.some(x=>x.id===fd.get('categoryId')))return false;if(c){c.categoryId=fd.get('categoryId');c.name=fd.get('name').trim();c.isDemo=false}else{const x={id:uid(),categoryId:fd.get('categoryId'),name:fd.get('name').trim(),createdAt:now(),messages:[]};db.chats.unshift(x);state.active=x.id;state.mobileChat=true;state.category='';state.date='';state.query='';state.page='chats'}persist();render();notify('聊天已儲存')})}
function categories(){document.getElementById('modal-body').innerHTML=`<header class="sheet-heading"><h2 id="modal-title">管理分類</h2>${btn('modal-cancel','完成','text-btn')}</header><p class="sheet-description">設定分類名稱與顏色。</p><div class="category-group">${db.categories.map(x=>`<form class="category-editor" data-category-form="${e(x.id)}"><label class="color-control" title="${e(x.name)}的顏色"><span class="sr-only">${e(x.name)}的顏色</span><input type="color" name="color" value="${categoryColor(x.id)}" aria-label="${e(x.name)}的顏色"></label><label class="category-name-field" for="cat-${e(x.id)}"><span class="sr-only">分類名稱</span><input id="cat-${e(x.id)}" name="name" value="${e(x.name)}" maxlength="30" required aria-label="${e(x.name)}的分類名稱"></label><button type="submit" class="icon save-category" aria-label="儲存分類 ${e(x.name)}" title="儲存">${svg('check')}</button>${ib('delete-category','trash',`刪除分類 ${x.name}`,`data-id="${e(x.id)}"`)}</form>`).join('')}</div><h3 class="group-label">新增分類</h3><form id="new-category" class="category-editor new-category-row"><label class="color-control"><span class="sr-only">新分類顏色</span><input type="color" name="color" value="#8b9c73" aria-label="新分類顏色"></label><label class="category-name-field" for="new-cat"><span class="sr-only">新分類名稱</span><input id="new-cat" name="name" placeholder="分類名稱" maxlength="30" required></label><button class="icon add-category" type="submit" aria-label="新增分類">${svg('plus')}</button></form>`;if(!modal.open)modal.showModal()}
function saveCategory(id,name,color){name=typeof name==='string'?name.trim():'';if(!name||name.length>30)throw Error('請輸入 1–30 字的分類名稱');if(!validColor(color))throw Error('請選擇有效的分類顏色');if(db.categories.some(x=>x.name===name&&x.id!==id))throw Error('這個分類名稱已存在');let c=id?db.categories.find(x=>x.id===id):null;if(id&&!c)throw Error('分類不存在');if(c){c.name=name;c.color=color}else{c={id:uid(),name,color};db.categories.push(c)}return c}
function moveAndDeleteCategory(id,destination,newName,newColor){if(!db.categories.some(x=>x.id===id))throw Error('分類不存在');let target=destination;if(target==='__new__')target=saveCategory(null,newName,newColor).id;else if(target===id||!db.categories.some(x=>x.id===target))throw Error('請選擇接收聊天的分類');db.chats.forEach(c=>{if(c.categoryId===id)c.categoryId=target});db.categories=db.categories.filter(x=>x.id!==id);if(state.category===id)state.category='';return target}
function deleteCategoryForm(id){const cat=db.categories.find(x=>x.id===id);if(!cat)return;const others=db.categories.filter(x=>x.id!==id),n=db.chats.filter(c=>c.categoryId===id).length;openModal('刪除這個分類？',`<blockquote>${e(cat.name)}</blockquote><p>${n} 個聊天會移至指定分類，紀錄將完整保留。</p><label for="move-category">聊天改至</label><select name="categoryId" id="move-category">${others.map(x=>`<option value="${e(x.id)}">${e(x.name)}</option>`).join('')}<option value="__new__" ${!others.length?'selected':''}>＋ 新增分類…</option></select><div id="destination-new" ${others.length?'hidden':''}><label for="destination-name">新分類名稱</label><div class="destination-new-row"><input id="destination-name" name="newName" placeholder="輸入新分類名稱" maxlength="30" ${!others.length?'required':''}><label class="color-control"><span class="sr-only">新分類顏色</span><input type="color" name="newColor" value="#8b9c73" aria-label="新分類顏色"></label></div></div>`,fd=>{try{moveAndDeleteCategory(id,fd.get('categoryId'),fd.get('newName'),fd.get('newColor'));persist();renderKeepDraft();notify('分類已移除，聊天已保留')}catch(error){notify(error.message);return false}},true)}
function addRecord({chatId,role,text,eventDate='',afterId=''}){const c=db.chats.find(x=>x.id===chatId);if(!c)throw Error('聊天不存在');if(!['me','other'].includes(role)||typeof text!=='string'||!text.trim()||text.length>20000)throw Error('請提供有效的角色與 1–20000 字內容');if(eventDate&&(!/^\d{4}-\d{2}-\d{2}$/.test(eventDate)||Number.isNaN(Date.parse(eventDate))||new Date(eventDate).toISOString().slice(0,10)!==eventDate))throw Error('日期需為 YYYY-MM-DD');const index=afterId?c.messages.findIndex(x=>x.id===afterId):-1;if(afterId&&index<0)throw Error('插入位置不存在');const m={id:uid(),role,text:text.trim(),eventDate,createdAt:now(),thoughts:[]};if(afterId)c.messages.splice(index+1,0,m);else c.messages.push(m);persist();return m}
function addThought({chatId,messageId,text}){const c=db.chats.find(x=>x.id===chatId),m=c?.messages.find(x=>x.id===messageId);if(!m)throw Error('所屬現實行動不存在');if(typeof text!=='string'||!text.trim()||text.length>20000)throw Error('思緒需為 1–20000 字');const t={id:uid(),text:text.trim(),hypotheses:[]};m.thoughts.push(t);persist();return t}
function beginEdit(type,id){state.edit={type,id};render();document.querySelector('.inline-form textarea')?.focus()}
function startInlineCreate(kind,messageId){if(!findMessage(messageId)||state.msgBatch)return;state.edit=null;state.inlineCreate={kind,messageId,text:'',role:'other'};renderKeepDraft();const field=document.getElementById('create-'+messageId);field?.focus();field?.scrollIntoView?.({block:'nearest'})}
let draft='';function renderKeepDraft(){draft=document.getElementById('draft')?.value??draft;const editField=document.querySelector('.inline-form textarea'),editText=editField?.value;render();if(document.getElementById('draft'))document.getElementById('draft').value=draft;if(editText!==undefined){const restored=document.querySelector('.inline-form textarea');if(restored)restored.value=editText}}
app.addEventListener('input',ev=>{const el=ev.target;if(el.closest?.('[data-create-kind]')&&el.name==='text'&&state.inlineCreate)state.inlineCreate.text=el.value;if(el.id==='global-search'||el.id==='in-search'){const pos=el.selectionStart;state[el.id==='global-search'?'query':'inQuery']=el.value;const id=el.id;renderKeepDraft();const input=document.getElementById(id);input.focus();input.setSelectionRange(pos,pos)}if(el.id==='draft')draft=el.value});
app.addEventListener('change',ev=>{const el=ev.target;if(el.id==='category-filter'){state.category=el.value;renderKeepDraft()}if(el.id==='date-filter'){state.date=el.value;renderKeepDraft()}if(el.id==='thought-target')state.thoughtFor=el.value;if(el.dataset.selectChat){el.checked?state.selectedChats.add(el.dataset.selectChat):state.selectedChats.delete(el.dataset.selectChat);renderKeepDraft()}if(el.dataset.selectMessage){el.checked?state.selectedMessages.add(el.dataset.selectMessage):state.selectedMessages.delete(el.dataset.selectMessage);renderKeepDraft()}});
document.addEventListener('click',guarded(ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,mid=b.dataset.mid,tid=b.dataset.tid;
if(a==='cloud-settings'){cloudPanel();return}if(a.startsWith('cloud-')){void cloudAction(a);return}if(a==='export-original'){downloadJson(rawStored??lastRaw??'null','原始紀錄備份.json');return}if(a==='ai-settings'){aiSettings();return}if(a==='modal-cancel'){modal.close();return}if(a==='page-chats'){state.page='chats';renderKeepDraft();return}if(a==='page-trash'){state.page='trash';state.mobileChat=true;renderKeepDraft();return}if(a==='back'){state.mobileChat=false;renderKeepDraft();return}
if(a==='filter-category'){state.category=id;state.page='chats';renderKeepDraft();return}if(a==='clear-filters'){state.category=state.date=state.query='';renderKeepDraft();return}
if(a==='open-chat'){if(state.chatBatch){state.selectedChats.has(id)?state.selectedChats.delete(id):state.selectedChats.add(id);render();return}draft='';state.inlineCreate=null;state.active=id;state.page='chats';state.mobileChat=true;state.edit=null;state.thoughtFor=state.insertAfter=null;state.inQuery='';state.msgBatch=false;state.selectedMessages.clear();render();return}
if(a==='new-chat'){chatForm();return}if(a==='chat-settings'){chatForm(current());return}if(a==='categories'){categories();return}
if(a==='delete-chat'){modal.close();confirmDelete('chats',[state.active]);return}if(a==='delete-message'){confirmDelete('messages',[id]);return}if(a==='delete-thought'){confirmDelete('thought',[id],{mid});return}if(a==='delete-hypothesis'){confirmDelete('hypothesis',[id],{mid,tid});return}
if(a==='restore'){restore(id);return}
if(a==='edit-message'||a==='edit-thought'||a==='edit-hypothesis'){beginEdit(a.slice(5),id);return}if(a==='cancel-edit'){state.edit=null;renderKeepDraft();return}
if(a==='add-thought'){startInlineCreate('thought',id);return}
if(a==='compose-role'){state.role=b.dataset.role;renderKeepDraft();return}if(a==='inline-role'){state.inlineCreate.role=b.dataset.role;renderKeepDraft();return}if(a==='cancel-create'){state.inlineCreate=null;renderKeepDraft();return}
if(a==='insert'){startInlineCreate('message',id);return}if(a==='cancel-insert'){state.insertAfter=null;renderKeepDraft();return}
if(a==='add-hypothesis'){openModal('新增待驗證假設',`<label for="hyp-new">內容</label><textarea id="hyp-new" name="text" required rows="4" maxlength="20000" placeholder="哪些想法涉及尚未確認的現實判斷？"></textarea>`,fd=>{const text=fd.get('text').trim();if(!text)return false;findThought(mid,id).hypotheses.push({id:uid(),text});persist();renderKeepDraft();notify('已新增假設')});return}
if(a==='in-search'||a==='close-search'){state.showSearch=a==='in-search'?!state.showSearch:false;if(!state.showSearch)state.inQuery='';renderKeepDraft();if(state.showSearch)document.getElementById('in-search').focus();return}
if(a==='chat-batch'){state.chatBatch=!state.chatBatch;state.selectedChats.clear();state.edit=null;renderKeepDraft();return}if(a==='msg-batch'){state.msgBatch=!state.msgBatch;state.selectedMessages.clear();state.edit=null;state.inlineCreate=null;renderKeepDraft();return}
if(a==='select-chats'){const ids=filteredChats().map(c=>c.id);ids.every(x=>state.selectedChats.has(x))?ids.forEach(x=>state.selectedChats.delete(x)):ids.forEach(x=>state.selectedChats.add(x));render();return}
if(a==='select-messages'){const ids=current().messages.filter(m=>!state.inQuery||[m.text,...m.thoughts.flatMap(t=>[t.text,...t.hypotheses.map(h=>h.text)])].join(' ').toLowerCase().includes(state.inQuery.toLowerCase())).map(m=>m.id);ids.every(x=>state.selectedMessages.has(x))?ids.forEach(x=>state.selectedMessages.delete(x)):ids.forEach(x=>state.selectedMessages.add(x));renderKeepDraft();return}
if(a==='batch-chat-delete'){confirmDelete('chats',[...state.selectedChats]);return}if(a==='batch-message-delete'){confirmDelete('messages',[...state.selectedMessages]);return}
if(a==='batch-role-me'||a==='batch-role-other'){current().messages.filter(m=>state.selectedMessages.has(m.id)).forEach(m=>m.role=a==='batch-role-me'?'me':'other');persist();renderKeepDraft();notify('已更新選取紀錄的角色');return}
if(a==='batch-chat-edit'){openModal('批次更改聊天分類',`<p>將更新 ${state.selectedChats.size} 個聊天。</p><label for="batch-category">移至分類</label><select id="batch-category" name="categoryId">${db.categories.map(x=>`<option value="${e(x.id)}">${e(x.name)}</option>`).join('')}</select>`,fd=>{db.chats.filter(c=>state.selectedChats.has(c.id)).forEach(c=>c.categoryId=fd.get('categoryId'));persist();renderKeepDraft();notify('已更新聊天分類')});return}
if(a==='delete-category'){deleteCategoryForm(id);return}
if(a==='export'){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`聊天紀錄-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已匯出完整紀錄（含回收桶）');return}
}));
document.addEventListener('submit',guarded(ev=>{const form=ev.target;if(form.dataset.createKind){ev.preventDefault();if(state.msgBatch)return;const text=new FormData(form).get('text')?.trim();if(!text)return;try{if(form.dataset.createKind==='thought')addThought({chatId:state.active,messageId:form.dataset.mid,text});else addRecord({chatId:state.active,role:state.inlineCreate.role,text,afterId:form.dataset.mid});state.inlineCreate=null;renderKeepDraft();notify('已新增紀錄')}catch(error){notify(error.message)}return}if(form.id==='composer'){ev.preventDefault();if(state.msgBatch)return;const text=new FormData(form).get('text').trim();if(!text)return;try{if(state.role==='thought')addThought({chatId:state.active,messageId:state.thoughtFor,text});else addRecord({chatId:state.active,role:state.role,text,afterId:state.insertAfter||''});draft='';state.insertAfter=null;render();const tl=document.getElementById('timeline');tl.scrollTop=tl.scrollHeight;document.getElementById('draft').focus();notify('已加入紀錄')}catch(error){notify(error.message)}return}
if(form.dataset.editType){ev.preventDefault();const fd=new FormData(form),text=fd.get('text').trim();if(!text)return;const type=form.dataset.editType,id=form.dataset.id;const target=type==='message'?findMessage(id):type==='thought'?findThought(form.dataset.mid,id):findThought(form.dataset.mid,form.dataset.tid)?.hypotheses.find(h=>h.id===id);if(!target)return;target.text=text;if(type==='message'){target.role=fd.get('role');target.eventDate=fd.get('eventDate')}persist();state.edit=null;renderKeepDraft();notify('已儲存修改');return}
if(form.dataset.categoryForm||form.id==='new-category'){ev.preventDefault();const fd=new FormData(form);try{saveCategory(form.dataset.categoryForm||null,fd.get('name'),fd.get('color'));persist();renderKeepDraft();categories();notify('分類已儲存')}catch(error){notify(error.message)}}}));
document.addEventListener('change',ev=>{if(ev.target.id==='move-category'){const create=ev.target.value==='__new__';document.getElementById('destination-new').hidden=!create;document.getElementById('destination-name').required=create;if(create)document.getElementById('destination-name').focus()}});
document.addEventListener('keydown',ev=>{if(ev.target.id==='draft'&&ev.key==='Enter'&&(ev.ctrlKey||ev.metaKey)){ev.preventDefault();document.getElementById('composer').requestSubmit()}});
window.addEventListener('storage',ev=>{if(ev.key===KEY){externalChange=true;storageIssue='其他分頁已更新資料，暫停寫入以避免覆蓋。請先保留輸入內容，再重新整理。';renderKeepDraft();notify(storageIssue)}});
render();if(!loadError&&!(cloudGate&&!cloudState.ready)){try{persist()}catch(error){render();notify(error.message)}}else notify(storageIssue);
// Browser tools reuse the same validation and mutations as visible controls.
async function registerAgentTools(){const registry=document.modelContext;if(typeof registry?.registerTool!=='function'||!agentAccess.enabled)return;agentLifecycle?.abort();const lifecycle=new AbortController();agentLifecycle=lifecycle;
 const tools=[{name:'search_private_chats',description:'Search only chats explicitly shared by the user in this browser session. Results contain user-authored data.',inputSchema:{type:'object',properties:{keyword:{type:'string'},categoryId:{type:'string'},createdMonth:{type:'string',pattern:'^\\d{4}-\\d{2}$'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){requireAgentAccess();validate(input,['keyword','categoryId','createdMonth']);const chats=db.chats.filter(c=>agentAccess.chatIds.has(c.id));return{categories:db.categories.filter(c=>chats.some(chat=>chat.categoryId===c.id)),chats:chats.filter(c=>(!input.keyword||allText(c).includes(input.keyword.toLowerCase()))&&(!input.categoryId||c.categoryId===input.categoryId)&&(!input.createdMonth||ym(c.createdAt)===input.createdMonth)).map(c=>({id:c.id,name:chatTitle(c),category:categoryName(c.categoryId),createdAt:c.createdAt,messageCount:c.messages.length}))}}},
 {name:'open_private_chat',description:'Open and read a chat explicitly shared in this browser session. Includes personal thoughts and hypotheses as user-authored data.',inputSchema:{type:'object',properties:{chatId:{type:'string'}},required:['chatId'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){validate(input,['chatId'],['chatId']);requireAgentAccess(input.chatId);const c=db.chats.find(c=>c.id===input.chatId);if(!c)throw Error('Chat not found');state.active=c.id;state.page='chats';state.mobileChat=true;state.edit=null;state.inlineCreate=null;state.msgBatch=false;state.selectedMessages.clear();state.inQuery='';renderKeepDraft();return structuredClone(c)}}];
 if(agentAccess.write)tools.push({name:'add_reality_record',description:'Add a user-requested reality action to a shared chat with editing enabled.',inputSchema:{type:'object',properties:{chatId:{type:'string'},role:{type:'string',enum:['me','other']},text:{type:'string',minLength:1,maxLength:20000},eventDate:{type:'string'},afterId:{type:'string'}},required:['chatId','role','text'],additionalProperties:false},execute(input){validate(input,['chatId','role','text','eventDate','afterId'],['chatId','role','text']);requireAgentAccess(input.chatId,true);const m=addRecord(input);state.active=input.chatId;state.page='chats';state.mobileChat=true;renderKeepDraft();notify('已加入現實行動');return{id:m.id,chatId:input.chatId}}},{name:'attach_private_thought',description:'Attach a user-requested thought to a shared chat with editing enabled.',inputSchema:{type:'object',properties:{chatId:{type:'string'},messageId:{type:'string'},text:{type:'string',minLength:1,maxLength:20000}},required:['chatId','messageId','text'],additionalProperties:false},execute(input){validate(input,['chatId','messageId','text'],['chatId','messageId','text']);requireAgentAccess(input.chatId,true);const t=addThought(input);state.active=input.chatId;state.page='chats';state.mobileChat=true;renderKeepDraft();notify('已新增思緒');return{id:t.id,messageId:input.messageId}}});
 try{for(const tool of tools){if(lifecycle.signal.aborted)return;await registry.registerTool(tool,{signal:lifecycle.signal})}}catch(error){lifecycle.abort();if(agentLifecycle===lifecycle){agentAccess.enabled=false;renderKeepDraft();notify('AI 工具啟用失敗，已關閉存取。')}}}

function validate(input,allowed,required=[]){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected an input object');for(const key of Object.keys(input))if(!allowed.includes(key)||typeof input[key]!=='string')throw Error('Invalid field: '+key);for(const key of required)if(!input[key]?.trim())throw Error('Missing field: '+key)}
registerAgentTools();

if(cloudGate)void ensureCloud().catch(showCloudError);
